<script setup lang="ts">
import { computed, ref } from 'vue'
import type { ForumCircle, ForumMediaItem, ForumPost, ForumQuoteContent, ForumUser } from '../../../types/forum'
import ForumHeader from '../components/ForumHeader.vue'
import ForumFeedItem from '../components/ForumFeedItem.vue'
import ForumEmptyState from '../components/ForumEmptyState.vue'
const props=defineProps<{circle:ForumCircle;posts:ForumPost[];joined:boolean;busy:boolean;error:string}>()
const emit=defineEmits<{(e:'back'):void;(e:'join'):void;(e:'publish'):void;(e:'generate'):void;(e:'settings'):void;(e:'click-post',p:ForumPost):void;(e:'click-user',u:ForumUser):void;(e:'like',p:ForumPost):void;(e:'bookmark',p:ForumPost):void;(e:'preview-image',i:number,m:ForumMediaItem[]):void;(e:'click-quote',q:ForumQuoteContent):void}>()
const mode=ref<'latest'|'hot'>('latest');const searching=ref(false);const keyword=ref('')
const displayPosts=computed(()=>{const query=keyword.value.trim().toLowerCase();const filtered=query?props.posts.filter(item=>`${item.title||''} ${item.content} ${(item.topics||[]).join(' ')}`.toLowerCase().includes(query)):props.posts;return [...filtered].sort((a,b)=>mode.value==='latest'?Number(b.createdAt)-Number(a.createdAt):(b.likeCount+b.commentCount*2+b.shareCount*3)-(a.likeCount+a.commentCount*2+a.shareCount*3))})
</script>
<template>
  <div class="circle-view"><ForumHeader :title="circle.name" show-back @back="emit('back')"><template #right><div class="head-actions"><button class="search-button" type="button" aria-label="圈内搜索" @click="searching=!searching">⌕</button><button v-if="circle.administratorAccountIds.length" class="icon-more" type="button" @click="emit('settings')">•••</button></div></template></ForumHeader>
    <div v-if="searching" class="circle-search"><input v-model="keyword" type="search" placeholder="搜索圈内帖子、话题"><button v-if="keyword" type="button" @click="keyword=''">×</button></div>
    <div class="circle-scroll"><section class="circle-hero"><div class="hero-main"><span><img v-if="circle.avatar.includes(':')" :src="circle.avatar"><template v-else>{{circle.avatar||circle.name[0]}}</template></span><div><h2>{{circle.name}}</h2><p>{{circle.memberCount.toLocaleString()}} 人</p></div><button v-if="!joined" type="button" @click="emit('join')">加入</button><em v-else>已加入</em></div><p class="description">{{circle.description}}</p><div v-if="circle.tags.length" class="tags"><span v-for="tag in circle.tags" :key="tag">{{tag}}</span></div><p v-if="circle.announcement" class="announcement"><b>公告</b>{{circle.announcement}}</p><div class="circle-actions"><button :disabled="!joined" type="button" @click="emit('publish')">发帖</button><button v-if="circle.source==='user'" :disabled="busy" type="button" @click="emit('generate')">{{busy?'生成中…':'生成内容'}}</button></div><p v-if="error" class="error-line">{{error}}</p></section>
      <div class="feed-tabs"><button :class="{active:mode==='latest'}" type="button" @click="mode='latest'">最新</button><button :class="{active:mode==='hot'}" type="button" @click="mode='hot'">热门</button><small v-if="keyword">{{displayPosts.length}} 条结果</small></div><ForumFeedItem v-for="post in displayPosts" :key="post.id" :post="post" @click-post="emit('click-post',post)" @click-user="u=>emit('click-user',u)" @like="p=>emit('like',p)" @bookmark="p=>emit('bookmark',p)" @preview-image="(i,m)=>emit('preview-image',i,m)" @click-quote="q=>emit('click-quote',q)"/><ForumEmptyState v-if="!displayPosts.length" :title="keyword?'没有找到相关帖子':'圈子还很安静'" :description="keyword?'换个关键词试试':'发布第一篇内容，或在生成设置中包含这个圈子'"/>
    </div>
  </div>
</template>
<style scoped>
.circle-view{display:flex;flex-direction:column;height:100%;background:var(--sys-bg-primary,#f5f5f7)}.head-actions{display:flex;align-items:center;gap:1px}.icon-more,.search-button{width:30px;height:30px;border:0;border-radius:50%;background:transparent;color:var(--text-secondary,#666);padding:0;font:inherit}.icon-more{letter-spacing:1px}.search-button{font-size:20px}.circle-search{display:flex;flex:0 0 auto;align-items:center;margin:7px 12px;padding:0 9px;border-radius:9px;background:var(--sys-bg-secondary,#fff)}.circle-search input{min-width:0;flex:1;height:32px;border:0;background:transparent;color:var(--text-primary,#222);font:inherit;font-size:12px;outline:0}.circle-search button{width:25px;height:25px;border:0;border-radius:50%;background:transparent;color:var(--text-tertiary,#999);font-size:16px}.circle-scroll{flex:1;overflow:auto}.circle-hero{padding:14px 16px;background:var(--sys-bg-secondary,#fff)}.hero-main{display:flex;align-items:center;min-width:0;gap:11px}.hero-main>span{display:flex;flex:0 0 46px;height:46px;align-items:center;justify-content:center;overflow:hidden;border-radius:13px;background:var(--sys-bg-tertiary,#eceef1);font-size:17px;font-weight:650}.hero-main img{width:100%;height:100%;object-fit:cover}.hero-main>div{min-width:0;flex:1}.hero-main h2{margin:0 0 3px;overflow:hidden;font-size:16px;white-space:nowrap;text-overflow:ellipsis}.hero-main p{margin:0;color:var(--text-tertiary,#999);font-size:11px}.hero-main>button,.circle-actions button{height:29px;border:1px solid var(--accent-color,#2b7de9);border-radius:999px;background:transparent;color:var(--accent-color,#2b7de9);padding:0 12px;font-size:12px;white-space:nowrap}.hero-main>em{flex:0 0 auto;color:var(--text-tertiary,#999);font-size:10.5px;font-style:normal}.description{margin:11px 0 0;color:var(--text-secondary,#666);font-size:13px;line-height:1.5}.tags{display:flex;gap:5px;overflow:auto;margin-top:8px}.tags span{flex:0 0 auto;padding:3px 7px;border-radius:999px;background:var(--sys-bg-primary,#f3f4f6);color:var(--text-secondary,#777);font-size:9.8px}.announcement{margin:9px 0 0;padding:8px 10px;border-radius:9px;background:var(--sys-bg-primary,#f5f5f7);color:var(--text-secondary,#666);font-size:11.5px;line-height:1.45}.announcement b{margin-right:7px;color:var(--text-primary,#333)}.circle-actions{display:flex;gap:7px;margin-top:10px}.circle-actions button{border-color:var(--border-color,#ddd);color:var(--text-primary,#333)}.circle-actions button:disabled{opacity:.35}.error-line{margin:8px 0 0;color:#d04a4a;font-size:10.5px;line-height:1.4}.feed-tabs{display:flex;align-items:center;gap:16px;height:38px;padding:0 16px;background:var(--sys-bg-primary,#f5f5f7)}.feed-tabs button{height:100%;border:0;border-bottom:2px solid transparent;background:transparent;color:var(--text-tertiary,#999);padding:0 2px;font:inherit;font-size:11.5px}.feed-tabs button.active{border-color:var(--text-primary,#333);color:var(--text-primary,#333);font-weight:620}.feed-tabs small{min-width:0;flex:1;overflow:hidden;color:var(--text-tertiary,#999);font-size:9.5px;text-align:right;white-space:nowrap;text-overflow:ellipsis}@media(max-width:340px){.circle-hero{padding-left:12px;padding-right:12px}.hero-main>span{flex-basis:42px;height:42px}.hero-main>button{padding:0 9px}.feed-tabs{padding-left:12px;padding-right:12px}}
</style>
